            "currentOffsetCharacters": 12552,
            "currentText": "\ntest('fresh progress authority denial hides private data before any queue read and can recover through a new authenticated base',async()=>{\n const stamp='d'.repeat(64),approved={...data,reviewAccessStamp:stamp,canReview:true,canApproveProgress:true};\n const page={scope,projectId,reviewAccessStamp:stamp,reviewSection:'PROGRESS',reviewFilter:'PENDING',afterReview:null,reviewId:null,records:[],total:0,nextCursor:null,canReview:true,canApproveProgress:true};\n for(const [canReview,canApproveProgress,message]of[\n  [true,false,'La decisión de avance corresponde al administrador o director.'],\n  [false,false,'Tu cuenta no tiene permiso para revisar esta cola.'],\n  [false,true,'Tu cuenta no tiene permiso para revisar esta cola.'],\n ]){\n  panel.reset({opened:true,tab:'PROGRESS',data:approved,progressPendingRequested:true,receipt:'private-receipt',progressReceipt:{taskId:'task-synthetic',title:'Private prior decision',progress:20}},[{method:'GET',body:{...approved,canReview,canApproveProgress}},{method:'GET',body:approved},{method:'GET',body:page}]);\n  let tree=panel.render(props);await button(tree,'Abrir avances por revisar').props.onClick();tree=panel.render(props);\n  const denied=panel.snapshot();assert.equal(denied.notice,message);assert.equal(denied.data,null);assert.equal(denied.accessBlocked,true);assert.equal(denied.receipt,null);assert.equal(denied.progressReceipt,null);assert.equal(denied.busy,false);assert.equal(denied.retryAllowed,false);assert.deepEqual(denied.reviewPages,{ATTENDANCE:null,EVIDENCE:null,PROGRESS:null});assert.equal(panel.requests().length,1);assert.equal(panel.requests()[0].method,'GET');assert.equal(panel.requests()[0].input.reviewSection,undefined);assert.doesNotMatch(text(tree),/Ficha sintética|Evidencia sintética|Private prior decision/);assert.deepEqual(await panel.durable(scope),[]);\n  await button(tree,'Abrir avances por revisar').props.onClick();panel.render(props);const restored=panel.snapshot();assert.equal(restored.accessBlocked,false);assert.equal(restored.data.canApproveProgress,true);assert.equal(restored.reviewPages.PROGRESS.reviewAccessStamp,stamp);assert.equal(panel.requests().length,3);assert.equal(panel.requests().every(request=>request.method==='GET'),true);assert.equal(panel.requests()[1].input.reviewSection,undefined);assert.equal(panel.requests()[2].input.reviewSection,'PROGRESS');assert.equal(panel.requests()[2].input.reviewAccessStamp,stamp);assert.deepEqual(await panel.durable(scope),[]);\n }\n});\ntest('fresh evidence review remains independent of progress approval permission',async()=>{\n const stamp='e'.repeat(64),snapshot={...data,reviewAccessStamp:stamp,canReview:true,canApproveProgress:false};\n const page={scope,projectId,reviewAccessStamp:stamp,reviewSection:'EVIDENCE',reviewFilter:'PENDING',afterReview:null,reviewId:null,records:[],total:0,nextCursor:null,canReview:true,canApproveProgress:false};\n panel.reset({opened:true,tab:'EVIDENCE',data:snapshot,evidencePendingRequested:true},[{method:'GET',body:snapshot},{method:'GET',body:page}]);let tree=panel.render(props);await button(tree,'Abrir evidencias por revisar').props.onClick();panel.render(props);\n assert.equal(panel.snapshot().accessBlocked,false);assert.equal(panel.snapshot().data.canApproveProgress,false);assert.equal(panel.snapshot().reviewPages.EVIDENCE.reviewAccessStamp,stamp);assert.equal(panel.requests().length,2);assert.equal(panel.requests().every(request=>request.method==='GET'),true);assert.equal(panel.requests()[1].input.reviewSection,'EVIDENCE');assert.deepEqual(await panel.durable(scope),[]);\n});\n",
